old="previewState.view='daily30';previewState.anchor=currentAnchor('daily30');"
new="previewState.view='daily30';previewState.anchors.daily30=currentAnchor('daily30');previewState.anchors.week=currentAnchor('week');previewState.anchors.month=currentAnchor('month');"
